// The table of known keys (ADR-0184): for each object type in the CORE schema,
// the keys the schema defines, what sits under each key, and which keys are
// optional. Generated by `pnpm schema:generate` into known-keys.json; this
// module is the typed reader over that file.

import knownKeysData from './known-keys.json'

export type KnownValue =
  | { readonly kind: 'leaf' } // a scalar, an enum, or an array of scalars
  | { readonly kind: 'opaque' } // the schema leaves the value open
  | { readonly kind: 'object'; readonly type: string }
  | { readonly kind: 'union'; readonly tag: string; readonly types: readonly string[] } // a tagged union
  | { readonly kind: 'array'; readonly item: KnownValue }
  | { readonly kind: 'map'; readonly value: KnownValue } // a collection the model owns

export interface KnownType {
  readonly keys: Readonly<Record<string, KnownValue>>
  readonly optional: readonly string[]
}
export type KnownKeyTable = Readonly<Record<string, KnownType>>

export const KNOWN_ROOT_TYPE = 'Project'

/** The type names the generated table holds, so a lookup by one of them is known to exist. */
type GeneratedTypeName = keyof typeof knownKeysData
type GeneratedKeyTable = KnownKeyTable & Readonly<Record<GeneratedTypeName, KnownType>>

export const KNOWN_KEYS: GeneratedKeyTable = knownKeysData as GeneratedKeyTable

/** Names of the types whose keys include `extensions`, the root included. */
export function typesWithExtensions(): GeneratedTypeName[]
export function typesWithExtensions(table: KnownKeyTable): string[]
export function typesWithExtensions(table: KnownKeyTable = KNOWN_KEYS): string[] {
  return Object.keys(table).filter((typeName) => table[typeName]?.keys.extensions !== undefined)
}
